import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        String[] w = new String[n];
        for (int i = 0; i < n; i++) w[i] = next();
        Arrays.sort(w);
        long ans = 0;
        // Words with prefix w[i] form the sorted range [w[i], w[i] + '{'), since '{' follows 'z'.
        for (int i = 0; i < n; i++) {
            String key = w[i] + '{';
            int lo = i + 1, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (w[mid].compareTo(key) < 0) lo = mid + 1;
                else hi = mid;
            }
            ans += lo - i - 1;
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	n := readInt()
	w := make([]string, n)
	for i := range w {
		w[i] = readToken()
	}
	sort.Strings(w)
	ans := 0
	// Words with prefix w[i] form the sorted range [w[i], w[i] + "{"), since '{' follows 'z'.
	for i := 0; i < n; i++ {
		key := w[i] + "{"
		ans += sort.SearchStrings(w, key) - i - 1
	}
	fmt.Println(ans)
}
